INSERT INTO DimBroker (SK_BrokerID, BrokerID, ManagerID, FirstName, LastName, MiddleInitial, Branch, Office, Phone, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT CAST(ROW_NUMBER() OVER (ORDER BY EmployeeID) AS INT) AS SK_BrokerID, CAST(COALESCE(TRY_CAST(EmployeeID AS INT), 0) AS INT) AS BrokerID, CAST(NULLIF(CAST(ManagerID AS TEXT), '') AS INT) AS ManagerID, CAST(EmployeeFirstName AS TEXT) AS FirstName, CAST(HR.EmployeeLastName AS TEXT) AS LastName, CAST(NULLIF(EmployeeMI, '') AS TEXT) AS MiddleInitial, CAST(EmployeeBranch AS TEXT) AS Branch, CAST(EmployeeOffice AS TEXT) AS Office, CAST(EmployeePhone AS TEXT) AS Phone, CAST(TRUE AS BOOLEAN) AS IsCurrent, CAST(1 AS INT) AS BatchID, CAST('1990-01-01' AS DATE) AS EffectiveDate, CAST('9999-12-31' AS DATE) AS EndDate FROM Source.HR WHERE EmployeeJobCode = 314;
